<div class="potentiality-block" @click="closePotentiality()"><div class="monster-list-block"><div class="monster-list" @click.stop="()=&gt;{}"><div class="monster-list-item" v-for="(monster,index) in playerMes.monsterList" :class="selectMonsterUse===index ? 'monster-list-item-active' : ''" @click="selectMonsterUse = index"><div class="monster-list-item-name">{{monster.name}}</div><div class="monster-list-item-level">{{monster.level}}</div></div></div></div><div class="monster-list-block" v-if="selectMonsterUse!=-1"><div class="select-block"> <div class="select-title" @click.stop="selectTitleClick('道具使用')" :class="selectTitle==='道具使用' ? 'select-title-active' : ''">道具使用</div><div class="select-title" @click.stop="selectTitleClick('潜力分配')" :class="selectTitle==='潜力分配' ? 'select-title-active' : ''">潜力分配</div><div class="select-title" @click.stop="selectTitleClick('技能更换')" :class="selectTitle==='技能更换' ? 'select-title-active' : ''">技能更换</div></div><div class="monster-list" @click.stop="()=&gt;{}" v-if="selectTitle==='道具使用'"><div class="shop-block"><div class="shop-text">使用等级提升卡</div><el-popover placement="left" width="150px" trigger="click"><template #reference><div class="shop-num">{{upgradeNum}} 张</div></template><el-input-number v-model="upgradeNum" :min="0" :max="getMaxUpgradeNum()" size="small"></el-input-number></el-popover><el-button class="shop-button" type="primary" size="small" @click="sureUpgrade()">确认使用</el-button></div></div><div class="monster-list" @click.stop="()=&gt;{}" v-if="selectTitle==='潜力分配'"><div class="potentiality-num-block"><div class="potentiality-num">{{getPotentiality(playerMes.monsterList[selectMonsterUse].level,playerMes.monsterList[selectMonsterUse].potentiality)}}</div><div class="potentiality-num-text">剩余潜力</div><div class="potentiality-button-text">保存</div><el-button type="success" :icon="Check" circle style="margin-right: 10px;margin-top:10px;float:right" @click="keepPlayMes()"> </el-button></div><div class="potentiality-mes-block" v-for="item of Object.keys(playerMes.monsterList[selectMonsterUse].potentiality)"><div class="potentiality-mes-text">{{getPotentialityName(item)}}</div><div class="potentiality-mes-line-block"><div class="potentiality-mes-line" :style="getLineStyle(item,playerMes.monsterList[selectMonsterUse])"></div></div><el-popover placement="left" width="150px" trigger="click"><template #reference><div class="potentiality-mes-num">{{playerMes.monsterList[selectMonsterUse].potentiality[item]}}</div></template><el-input-number v-model="playerMes.monsterList[selectMonsterUse].potentiality[item]" :min="0" :max="getInputMax(playerMes.monsterList[selectMonsterUse],item)" size="small"></el-input-number></el-popover></div></div><div class="monster-list" @click.stop="()=&gt;{}" v-if="selectTitle==='技能更换'"><div class="monster-skill-button-block"><el-button type="success" :icon="Check" circle style="margin-right: 10px;margin-top:10px;float:right" @click="keepPlayMes()"> </el-button><div class="monster-skill-button-text">保存</div></div><div class="monster-skill-block"><el-input class="monster-skill-input" v-model="inputSkill" size="small" placeholder="请输入技能名称"></el-input><div class="monster-skill-all"><div class="monster-skill-all-for" v-for="skill in playerMes.monsterList[selectMonsterUse].allSkillList" :key="skill.name" :class="skill.using ? 'monster-skill-all-for-active' : ''" @click="clickSkillAll(skill.name)" v-show="skill.name.includes(inputSkill)"> <div class="monster-skill-all-for-name">{{skill.name}}</div><div class="monster-skill-all-for-level">{{skill.level||'?'}}</div></div><div class="monster-skill-all-for" style="background-color:#ff9d9d;" v-for="skill in playerMes.monsterList[selectMonsterUse].canLearnSkillList" :key="skill.name" v-show="skill.name.includes(inputSkill)" @click="store.commit('hajimiReset/setTipList', ['此技能需要'+skill.level+'级才能解锁!'])"> <div class="monster-skill-all-for-name" style="padding-left: 12px">{{skill.name}}</div><div class="monster-skill-all-for-level">{{skill.level||'?'}}</div><div class="monster-skill-all-for-img"></div></div></div></div><div class="monster-skill-block"><div class="monster-skill-use"><div class="monster-skill-use-for" v-for="skill in playerMes.monsterList[selectMonsterUse].skillList" :key="skill" @click="clickSkillUse(skill)">{{skill}}</div></div></div><el-popconfirm title="确认进化吗？" placement="left-end" @confirm="evolveMonster(playerMes.monsterList[selectMonsterUse])"><template #reference><el-button class="monster-evolve-button" type="primary" size="small" text bg v-if="canEvolve(playerMes.monsterList[selectMonsterUse])">进化</el-button></template></el-popconfirm></div></div></div>